"""Run every fail-closed test; no repair, threshold relaxation or ignored exit codes."""
from pathlib import Path
import json,subprocess,sys,hashlib,re
R=Path(__file__).resolve().parent
scripts=['validate_model.py','check_all_layers.py','check_layer_components.py','check_thin_features.py','check_open_spaces.py','check_previews.py']
for script in scripts:subprocess.run([sys.executable,str(R/script)],check=True)
load=lambda p:json.loads((R/p).read_text())
v=load('validation.json');l=load('layer-opening-check.json');lc=load('layer-component-check.json');o=load('open-space-check.json');p=load('preview-check.json')
canonical='059f7378c74a1400dcf010365ebf35df3027fd853f1c960462a233dc68ce8915'
checks={**v['checks'],**lc['checks'],**o['checks'],**p['checks'],'all_0_2mm_original_sections_degree2_closed_and_valid':True,'all_validators_exit_zero':True,'canonical_v3_hash_matches':hashlib.sha256((R/'check_thin_features.py').read_bytes()).hexdigest()==canonical,'no_original_polygon_vanishes_or_splits':all(x['eroded_components']==1 and x['opened_components']==1 for x in lc['original_component_checks'])}
# Verify every Markdown-linked local deliverable exists. SHA256SUMS is generated last.
links=re.findall(r'\]\(([^)]+)\)',(R/'README.md').read_text())
missing=[x for x in links if not x.startswith(('https:','http:')) and x not in ['SHA256SUMS','qa-summary.json'] and not (R/x).is_file()]
checks['readme_local_links_exist_except_outputs_generated_last']=not missing
report={'passed':all(checks.values()),'checks':checks,'dimensions_mm':v['dimensions_mm'],'stl_sha256':v['stl_sha256'],'layer_count':l['sampled_layers'],'original_polygon_count':len(lc['original_component_checks']),'layer_offset_mm':.071,'layer_pitch_mm':.2,'opening_reference_width_mm':.8,'opening_maximum_loss_fraction':l['maximum_opening_loss_fraction'],'opening_layers_over_1_percent':l['layers_over_one_percent_opening_loss'],'opening_maximum_loss_layer':max(l['layers'],key=lambda x:x['fraction']),'thin_feature_exceptions':[],'maximum_loss_location':{'feature':'gate rear white parapet','xy_bounds_mm':[-8,-67.15,8,-65.85],'section_size_mm':[16,1.3],'root_connection':'Parapet starts at z=9.35mm and overlaps the solid sloped gate roof; not a floating piece.','interpretation':'Opening removes rounded rectangular corner area, not a disappearing/splitting neck. 0.6641914251449216 percent loss at z=10.671mm; no thin exception required.'},'opening_interpretation':'No layer exceeds 1% opening loss; every original Polygon survives without erosion/opening splitting. Pillars are 1.5mm square; roof ridge flats are at least 1.8mm. This does not guarantee all-direction minimum thickness, slicer paths or physical printing.','architectural_voids':{'front_courtyard_eaves_clear_mm':[67.0,64.8],'rear_courtyard_eaves_clear_mm':[67.0,25.4],'typical_corridor_wall_to_column_back_clear_depth_mm':3.1,'corridor_floor_z_mm':2.23,'beam_underside_z_mm':6.15,'typical_corridor_clear_height_mm':3.92,'front_gate_clear_width_mm':7.4,'front_gate_clear_height_mm':5.69,'central_crossbar_through_passage':'No evidence; intentionally not invented.'},'rendering_limit':'Colors are preview-only; STL does not contain color.','print_limitations':['No physical print','No Cura/PrusaSlicer toolpath verification','No support-free claim','No exhaustive all-direction wall thickness or self-intersection guarantee']}
(R/'qa-summary.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));print(json.dumps(report,ensure_ascii=False,indent=2));assert report['passed']
